// === Tab: mySketch ===
let S, N = 17, SPT = 3;

function setup() {
  createCanvas(windowWidth, windowHeight);
  S = max(width, height);
  S = ~~(S / N / SPT) * SPT;
  frameRate(30);
}

function draw() {
  let bass = (typeof sub_bass !== 'undefined') ? sub_bass : (typeof bass_ratio !== 'undefined' ? bass_ratio : 0);
  let perc = (typeof percussive !== 'undefined') ? percussive : 0;

  background(26, 26, 36);

  S = max(width, height);
  S = ~~(S / N / SPT) * SPT;

  const sw = (S / SPT) * (0.8 + bass * 0.4);
  strokeWeight(sw);

  stroke("#3DB2FF"); 
  makeLines(1, perc);

  stroke("#FF2442"); 
  makeLines(-1, perc);

  stroke("#FFB830"); 
  makeLines(0.5, bass);
}

function makeLines(dir = 1, reactivity = 0) {
  let sw = S / SPT;
  push();
  translate(width / 2, height / 2);
  let rot = sin(frameCount * 0.02 * dir) * 0.15 + reactivity * 0.1 * dir;
  rotate(rot);
  translate(-width / 2 + sin(frameCount * 0.03) * (S / SPT), -height / 2 + cos(frameCount * 0.03) * (S / SPT));
  const dx = S + S;
  for (let x = -dx; x < width + dx; x += sw + sw) {
    line(x, -dx, x, height + dx);
  }
  pop();
}
